from itertools import combinations
from typing import FrozenSet, List, Optional, Iterable

Edge = FrozenSet[int]
Hypergraph = List[Edge]


def is_monochromatic(edge: Edge, red: FrozenSet[int]) -> bool:
    """An edge is bad if it is entirely red (subset of R) or entirely blue."""
    return (edge <= red) or edge.isdisjoint(red)


def find_proper_coloring(H: Hypergraph, n: int) -> Optional[FrozenSet[int]]:
    """Exhaustively scan all 2^n red sets; return the first proper one."""
    for size in range(n + 1):
        for combo in combinations(range(n), size):
            red = frozenset(combo)
            if all(not is_monochromatic(e, red) for e in H):
                return red
    return None


def is_non_two_colorable(H: Hypergraph, n: int) -> bool:
    return find_proper_coloring(H, n) is None


if __name__ == "__main__":
    triangle: Hypergraph = [frozenset({0, 1}), frozenset({1, 2}), frozenset({0, 2})]
    print("triangle proper colouring:", find_proper_coloring(triangle, 3))  # None
    print("triangle non-two-colourable:", is_non_two_colorable(triangle, 3))  # True

from itertools import combinations
from typing import FrozenSet, List, Tuple

Edge = FrozenSet[int]
Hypergraph = List[Edge]


def proper_exists(H: Hypergraph, n: int) -> bool:
    for size in range(n + 1):
        for combo in combinations(range(n), size):
            red = frozenset(combo)
            if all(not (e <= red or e.isdisjoint(red)) for e in H):
                return True
    return False


def m_bruteforce(k: int, max_vertices: int) -> Tuple[int, Hypergraph]:
    """Return (m(k)-candidate, witness) by scanning increasing edge counts."""
    for num_edges in range(1, 2 ** max_vertices + 1):
        for n in range(k, max_vertices + 1):
            base = [frozenset(c) for c in combinations(range(n), k)]
            for chosen in combinations(base, num_edges):
                H = list(chosen)
                if not proper_exists(H, n):
                    return num_edges, H
    raise RuntimeError("increase max_vertices")


if __name__ == "__main__":
    for k, mv in ((1, 2), (2, 4)):
        edges, H = m_bruteforce(k, mv)
        print(f"m({k}) = {edges}, witness = {[sorted(e) for e in H]}")

