def verify_lower_bound(k: int, n: int) -> bool:
    """Confirm every k-uniform hypergraph on n vertices with < 2^(k-1) edges
    is two-colourable, i.e. the Erdos threshold really is a colourability
    certificate."""
    threshold = 2 ** (k - 1)
    base = [frozenset(c) for c in combinations(range(n), k)]
    for num_edges in range(threshold):
        for chosen in combinations(base, num_edges):
            if not proper_exists(list(chosen), n):
                return False
    return True


if __name__ == "__main__":
    for k in (1, 2, 3):
        print(f"k={k}: threshold 2^(k-1)={2**(k-1)}, "
              f"all sparse hypergraphs colourable: {verify_lower_bound(k, 2*k+1)}")

