from typing import FrozenSet


def interval_count(n: int, s: FrozenSet[int]) -> int:
    """Number of subsets A of {0,...,n-1} with S subset A (equivalently, the
    number disjoint from S). By the Boolean-lattice interval identity this is
    exactly 2^(n - |S|); computed here in O(1)."""
    return 2 ** (n - len(s))


def bad_colorings_upper_bound(n: int, k: int, num_edges: int) -> int:
    """Union-bound estimate of colourings monochromatic on some edge:
    each edge of size >= k forbids at most 2^(n-k+1) colourings."""
    return num_edges * 2 ** (n - k + 1)

